DROP TABLE IF EXISTS `cars`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `cars` (
  `id_car` int NOT NULL AUTO_INCREMENT,
  `id_category` int NOT NULL,
  `model` varchar(45) NOT NULL,
  `year_car` year NOT NULL,
  `description` text NOT NULL,
  `image_path` varchar(255) NOT NULL,
  `is_deleted` tinyint NOT NULL,
  `price` decimal(10,2) NOT NULL DEFAULT '0.00',
  `power_hp` int DEFAULT NULL COMMENT 'Мощность в л.с.',
  `id_fuel_type` int DEFAULT NULL,
  `id_treansmission` int DEFAULT NULL,
  PRIMARY KEY (`id_car`),
  KEY `cat_idx` (`id_category`),
  KEY `fuels_types_idx` (`id_fuel_type`),
  KEY `transmissions_idx` (`id_treansmission`),
  CONSTRAINT `cat` FOREIGN KEY (`id_category`) REFERENCES `categories` (`id_category`),
  CONSTRAINT `fuels_types` FOREIGN KEY (`id_fuel_type`) REFERENCES `fuels_types` (`id`),
  CONSTRAINT `transmissions` FOREIGN KEY (`id_treansmission`) REFERENCES `transmissions` (`id`)
) ENGINE=InnoDB AUTO_INCREMENT=22 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci;
/*!40101 SET character_set_client = @saved_cs_client */;

