INSERT INTO `cars` VALUES (1,3,'AMG CLE 53',2024,'3.0 рядная «шестёрка» M256M с электротурбиной (449 л.с., 560 Нм + 200 Нм от 48V стартер-генератора), полный привод 4MATIC+, 9-ступенчатый AMG Speedshift TCT. Разгон 0-100 за 4.2 с. Задние подруливающие колёса (до 2.5°), дрифт-режим (Drift Mode), пневмоподвеска с автоматическим уровнем кузова. Салон: кресла AMG Performance в кожзаме с микроволокном, руль с тремя спицами и круглым контроллером режимов, салонная подсветка 64 цветами, медиасистема MBUX с 11.9\" планшетом.','mercedes53.jpg',0,5500.00,435,2,1),(2,3,'E63 W212',2015,'Mercedes-Benz E63 W212 — это легендарный спортивный седан (и универсал), выпускавшийся с 2009 по 2016 год. Он сочетает комфорт бизнес-класса с суперкаровской динамикой. Автомобиль оснащался двумя мощнейшими V8 двигателями и предлагался как в заднеприводной (ранние версии), так и в полноприводной модификациях','mercedes212.jpg',0,10000.00,306,1,1),(3,1,'Camry',2021,'2.5 A25A-FKS (181 л.с., 231 Нм) или 3.5 V6 2GR-FKS (249 л.с., 356 Нм), передний привод, вариатор Direct Shift CVT с первой гидро-передачей (имитирует старт с автомата). Разгон: 9.1 с (2.5) или 7.5 с (3.5). Система Toyota Safety Sense 2.0: автоторможение, распознавание пешеходов и велосипедистов, ночной автосвет, адаптивный круиз. Салон: кожа, электрорегулировка водителя с памятью, 9\" медиасистема с JBL (опция), трёхзонный климат-контроль, подогрев всех кресел и руля.','toyotaCamry.jpg',0,1400.00,249,2,1),(4,1,'Supra',2025,'Toyota Supra — это легендарный японский спортивный автомобиль класса Gran Turismo, выпускающийся с 1978 года. Модель прославилась благодаря идеальной развесовке, заднему приводу и выдающимся характеристикам, став культовой классикой в мире дрифта, автоспорта и тюнинга','toyotaSupra.jpg',0,25000.00,340,1,1),(5,2,'M5 F90',2018,'4.4 V8 twin-turbo (600 л.с., 750 Нм), M xDrive с заднеприводным режимом (2WD), 8-ступенчатый M Steptronic. Разгон 0-100 за 3.4 с. Адаптивная подвеска M с электронноуправляемыми амортизаторами, активный M-дифференциал. Карбоновая крыша для снижения центра тяжести, лазерные фары BMW Laserlight, спортивная выхлопная система с регулируемыми заслонками. ','bmwM5.jpg',0,4500.00,600,2,1),(6,2,'M5 E34',1992,'3.8 рядная «шестёрка» (340 л.с., 400 Нм), задний привод, 5-ступенчатая механика Getrag. Разгон 0-100 за 5.9 с (для своего времени — феномен). Подвеска: McPherson спереди, многорычажка сзади, заниженный спортивный клиренс. Салон: кожа Nappa, передние кресла с электрорегулировкой и подогревом, бортовой компьютер с 13 кнопками. Культовый «броневик» с узнаваемыми порогами и обвесом.','bmwE34.jpg',0,3500.00,192,2,3),(7,8,'Q3',2018,'2.0 TFSI (180 л.с., 320 Нм), полный привод Quattro, 7-ступенчатый робот S tronic. Разгон 0-100 за 7.8 с. Подвеска независимая (McPherson спереди, многорычажка сзади). Салон: виртуальная приборка Audi Virtual Cockpit 12.3\", медиасистема MMI с 8.8\" экраном, отделка кожей и алькантарой. Опции: адаптивный круиз-контроль, система помощи при парковке с камерами 360°, подогрев всех сидений, двухзонный климат-контроль. Багажник 530 л.','audiQ3.jpg',0,1500.00,180,1,5),(8,8,'RS7',2020,'4.0 V8 twin-turbo (600 л.с., 800 Нм), 48V мягкий гибрид, полный привод Quattro с самоблокирующимся дифференциалом, 8-ступенчатый Tiptronic. Разгон 0-100 за 3.6 с. Пневмоподвеска с адаптивными амортизаторами, задний подруливающий мост, карбон-керамические тормоза (опция). Салон: спортивные кресла RS с ромбовидной прострочкой, трёхэкранная медиасистема (12.3\" + два 10.1\"), отделка карбоном и алькантарой. Оптика Matrix LED с лазерными фарами дальнего света.','audiRS7.jpg',0,5000.00,600,1,1),(9,4,'Civic',2022,'1.5 турбо VTEC (182 л.с., 240 Нм), передний привод, вариатор с имитацией 7 ступеней (или 6-ступ. механика на версии Sport). Разгон 0-100 за 8.0 с. Подвеска: McPherson спереди, многорычажка сзади. Система Honda Sensing: автоторможение, адаптивный круиз с функцией Stop&Go, удержание в полосе, распознавание знаков. Салон: цифровая приборка 10.2\", медиасистема с 9\" экраном, Apple CarPlay/Android Auto беспроводные, отделка тканью с контрастной прострочкой. Расход топлива 6.8 л/100 км.','hondaCivic.jpg',0,1200.00,140,1,3),(10,4,'S2000',2004,'2.2 F22C (240 л.с., 220 Нм при 6800 об/мин), задний привод, 6-ступенчатая короткоходная механика. Красная зона — 9000 об/мин, VTEC открывается после 6000 об/мин. Разгон 0-100 за 6.2 с. Подвеска: двойные поперечные рычаги (перед и зад) — идеальная управляемость, алюминиевые кулаки. Электрический жёсткий верх (хардтоп) или тканевый в базе. Салон: алюминиевые педали, кресла с высокой поддержкой, трёхспицевый руль MOMO, цифровая панель с барграфом оборотов. Классика JDM без экранов.','hondaS2000.jpg',0,3000.00,240,1,3),(11,7,'K5',2020,'2.5 GDI (194 л.с., 245 Нм), передний привод, 8-ступенчатый автомат. Разгон 0-100 за 8.9 с. Подвеска: McPherson спереди, многорычажка сзади. Две 12.3-дюймовые панели: цифровая приборка и медиасистема. Подогрев лобового стекла (нити в стекле), система предотвращения столкновений в слепых зонах с выводом картинки на приборку, адаптивный круиз. Фирменные ДХО «звёздное небо» (Star Map Lighting). Салон: кожа Nappa с перфорацией, вентиляция передних сидений, подогрев задних.','kiaK5.jpg',0,1300.00,194,1,1),(12,6,'Priora',2013,'1.6 (98 л.с., 145 Нм), передний привод, 5-ступ. механика или 4-ступ. автомат Jatco. Разгон 0-100 за 11.5 с (механика). Гидроусилитель руля (у поздних версий — ЭУР). Кондиционер (не климат), подогрев передних сидений, электростеклоподъёмники всех дверей. Аудиосистема с USB и AUX. Бюджетный ремонт и обслуживание, запчасти с разборки копейки. Салон: тканевая обивка, пластик серого цвета без особых излишеств, но всё нужное есть.','ladaPriora.jpg',0,1000.00,98,2,3),(13,5,'Passat',2019,'2.0 TSI EA888 Gen3 (190 л.с., 320 Нм), передний привод, 7-ступ. DSG DQ381 (с мокрыми сцеплениями). Разгон 0-100 за 7.5 с. Матричные фары IQ.Light с 48 LED на сторону, проекционный экран на лобовое стекло, массаж передних сидений ErgoComfort с пневмоподушками. Салон: «виртуальная приборка» Active Info Display 10.25\", медиасистема с 9.2\" экраном, голосовое управление, ассистент парковки с маневрированием из выезда.','volkswagenPassat.jpg',0,1300.00,180,1,5),(14,5,'Polo',2020,'1.4 TSI (125 л.с., 200 Нм), передний привод, 7-ступ. DSG (DQ200 с сухими сцеплениями). Разгон 0-100 за 9.2 с. Подвеска: McPherson спереди, полузависимая балка сзади. Датчики дождя и света, ESP с функцией стабилизации прицепа, 6 подушек безопасности (передние, боковые, шторки). Салон: цифровая приборка Digital Cockpit (опция), 6.5\" мультимедиа, отделка глянцевым чёрным пластиком. Пространства сзади больше, чем у многих одноклассников — 5 человек не теснятся.','bmwM3.jpg',0,1000.00,431,1,5),(15,9,'LX570',2016,'5.7 V8 3UR-FE (367 л.с., 530 Нм), полный привод с понижающей передачей и блокировкой дифференциала, 8-ступенчатый автомат Aisin. Разгон 0-100 за 7.7 с (для 2.7 тонн). Рама лестничного типа, пневмоподвеска с регулировкой дорожного просвета (от 210 до 320 мм), система активной стабилизации против кренов. Салон: кожа полуанилин, вставки из настоящего дерева, четырёхзонный климат-контроль, подогрев/вентиляция всех сидений, массаж передних крёсел, аудиосистема Mark Levinson с 19 динамиками. ','lexus570.jpg',0,4500.00,383,1,1),(16,9,'LC500',2018,'5.0 V8 2UR-GSE (477 л.с., 540 Нм), задний привод с активным дифференциалом, 10-ступенчатый автомат Direct Shift с гидротрансформатором. Разгон 0-100 за 4.4 с. Подвеска многорычажная с алюминиевыми рычагами, адаптивные амортизаторы Lexus Dynamic Handling System. Карбоновые двери (опция), задний спойлер выезжает на скорости 80 км/ч. Салон: кресла из кожи L-Aniline с 12-позиционной регулировкой, тачпад на центральной консоли, проекционный дисплей, аудиосистема Mark Levinson Reference с 12 динамиками.','lexus500.jpg',0,6000.00,477,1,1),(17,10,'Model 3',2021,'Электромотор на задней оси (RWD) — 283 л.с. или Dual Motor AWD — 450 л.с. Разгон 0-100: 5.9 с (RWD) или 4.2 с (AWD). Батарея 60 кВт·ч (RWD) или 75 кВт·ч (Long Range). Запас хода 491-629 км по WLTP. Подвеска: двухрычажка спереди, многорычажка сзади. Одна 15.4\" центральная панель вместо приборки, автопилот базовый (адаптивный круиз + удержание в полосе), стеклянная крыша. ','teslaModel.jpg',0,2500.00,283,2,4),(18,10,'Roadster ',2023,'Три электромотора (один спереди, два сзади) — около 1000 л.с. на базовой версии, до 2000 л.с. на пакете Space X (с опциональными реактивными соплами для ускорения). Разгон 0-100 за 1.9 секунды (база) или 1.1 секунды с пакетом Space X. Максималка 400+ км/ч. Запас хода около 1000 км на батарее 200 кВт·ч. Карбоновый монокок, съёмная жёсткая крыша. Салон: 4 места, руль-штурвал (у ранних прототипов), 17\" экран как у Model S, отделка алькантара. ','teslaRoadster.jpg',0,15000.00,288,2,4),(19,11,'Arrizo 6 Pro',2024,'1.6 TGDI (150 л.с., 275 Нм) или 1.5 Turbo (147 л.с.), передний привод, вариатор CVT25 (с имитацией 9 ступеней). Разгон 0-100 за 9.2 с. Подвеска: McPherson спереди, многорычажка сзади. Две 12.3-дюймовые панели (приборка + медиа), система Sonos 8 динамиков, 6 подушек безопасности, адаптивный круиз с остановкой и стартом. Салон: экокожа с перфорацией, вентиляция передних сидений, подогрев всех кресел, отделка мягким пластиком с прострочкой. Китайский рынок — много опций за свои деньги.','chery6.jpg',0,1200.00,147,1,2),(20,11,'Chery Omoda 5',2023,'1.5 TGDI (147 л.с., 230 Нм) или 1.6 TGDI (186 л.с.) на полном приводе, передний привод или полный (4×4), вариатор CVT25 (1.5) или 7-ступ. робот DCT (1.6). Разгон 0-100 за 9.6 с (1.5) или 7.8 с (1.6). Подвеска: McPherson спереди, многорычажка сзади (на 4×4) или полузависимая балка (на переднем). 10.25\" приборка + 10.25\" медиасистема (объединены в один блок), ассистент движения в пробках, круговой обзор 360°, электрический доводчик дверей.','chery5.jpg',0,1300.00,147,1,2),(21,7,'Seitos',2025,'Компактный кроссовер на новой платформе K3. Двигатели на выбор: 2.0 MPI атмосферный (147 л.с., 179 Нм) в паре с вариатором IVT; либо 1.6 T-GDI турбо (180-195 л.с., 265 Нм) с 8-ступенчатым автоматом (в Корее — 193 л.с., в Европе — 180 л.с.). Также доступна гибридная версия HEV: 1.6 GDI + электромотор, суммарная мощность 178 л.с., 6-ступенчатый робот, e-AWD с дополнительным электромотором на задней оси, функция V2L (питание внешних приборов). Привод — передний или полный (AWD с многорычажной задней подвеской). Габариты выросли: длина 4430 мм, колёсная база 2690 мм, багажник 536 литров. Салон: три экрана — 12.3\" виртуальная приборка, 12.3\" тачскрин мультимедиа и 5\" дисплей климата. Опции: панорамная крыша, проекционный дисплей, аудиосистема Harman Kardon (или Bose), атмосферная подсветка 64 цвета, беспроводная зарядка, камеры кругового обзора. Безопасность: адаптивный круиз с Stop&Go, автоторможение, удержание в полосе, контроль слепых зон. В базе — 9 подушек безопасности (для Кореи). Выдвижные дверные ручки, вертикальные фары и сплошная световая полоса сзади.','kiaSeitos.jpg',0,1800.00,147,2,1);
